#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef long long ll;

typedef struct {
    ll val;
    int idx;
} Pair;

#define HASH_SIZE (1 << 20)
#define HASH_MASK (HASH_SIZE - 1)
#define EMPTY LLONG_MIN

typedef struct {
    ll *keys;
    int *vals;
} HT;

HT htU, htV;
Pair *Uarr, *Varr;
int *u_start, *u_end, *v_start, *v_end;

int N, Q;
ll K;
int A[200005];
int D[200005];
int p[200005];
int prev_less[200005], next_less[200005];
ll uval[200005], vval[200005];

static inline int hashKey(ll key) {
    unsigned long long x = (unsigned long long)key;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return (int)(x & HASH_MASK);
}

void ht_init(HT *ht) {
    ht->keys = (ll*)malloc(sizeof(ll) * HASH_SIZE);
    ht->vals = (int*)malloc(sizeof(int) * HASH_SIZE);
    for (int i = 0; i < HASH_SIZE; i++) ht->keys[i] = EMPTY;
}

int ht_get(HT *ht, ll key) {
    int h = hashKey(key);
    while (ht->keys[h] != EMPTY) {
        if (ht->keys[h] == key) return ht->vals[h];
        h = (h + 1) & HASH_MASK;
    }
    return -1;
}

void ht_put(HT *ht, ll key, int val) {
    int h = hashKey(key);
    while (ht->keys[h] != EMPTY && ht->keys[h] != key) {
        h = (h + 1) & HASH_MASK;
    }
    if (ht->keys[h] == EMPTY) {
        ht->keys[h] = key;
        ht->vals[h] = val;
    }
}

int cmpPair(const void *a, const void *b) {
    const Pair *p1 = (const Pair*)a;
    const Pair *p2 = (const Pair*)b;
    if (p1->val < p2->val) return -1;
    if (p1->val > p2->val) return 1;
    if (p1->idx < p2->idx) return -1;
    if (p1->idx > p2->idx) return 1;
    return 0;
}

int buildGroups(Pair *arr, int n, HT *ht, int *start, int *end) {
    qsort(arr, n, sizeof(Pair), cmpPair);
    int G = 0;
    int i = 0;
    while (i < n) {
        int j = i + 1;
        ll val = arr[i].val;
        while (j < n && arr[j].val == val) j++;
        start[G] = i;
        end[G] = j;
        ht_put(ht, val, G);
        G++;
        i = j;
    }
    return G;
}

static inline int lowerIdx(Pair *arr, int start, int end, int lo) {
    int l = start, r = end;
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (arr[mid].idx < lo) l = mid + 1;
        else r = mid;
    }
    return l;
}

static inline int upperIdx(Pair *arr, int start, int end, int hi) {
    int l = start, r = end;
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (arr[mid].idx <= hi) l = mid + 1;
        else r = mid;
    }
    return l;
}

static inline ll countVal(Pair *arr, HT *ht, int *start, int *end, ll val, int lo, int hi) {
    if (lo > hi) return 0;
    int g = ht_get(ht, val);
    if (g < 0) return 0;
    int s = start[g];
    int e = end[g];
    int l = lowerIdx(arr, s, e, lo);
    int r = upperIdx(arr, s, e, hi);
    return (ll)(r - l);
}

ll countPartners(int pos, int L, int R) {
    if (L > R) return 0;
    ll ans = 0;

    if (pos < L) {
        int lo = L;
        int hi = R;
        ll maxq = (ll)pos + K;
        if (maxq < hi) hi = (int)maxq;
        if (lo > hi) return 0;

        ans += countVal(Uarr, &htU, u_start, u_end, uval[pos] + K, lo, hi);
        ans += countVal(Varr, &htV, v_start, v_end, vval[pos] + K, lo, hi);

        ll eq = (ll)pos + K;
        if (eq >= L && eq <= R && eq <= N) {
            if (A[(int)eq] == A[pos]) ans--;
        }
    } else if (pos > R) {
        int lo = L;
        int hi = R;
        ll minq = (ll)pos - K;
        if (minq > lo) lo = (int)minq;
        if (lo > hi) return 0;

        ans += countVal(Uarr, &htU, u_start, u_end, uval[pos] - K, lo, hi);
        ans += countVal(Varr, &htV, v_start, v_end, vval[pos] - K, lo, hi);

        ll eq = (ll)pos - K;
        if (eq >= L && eq <= R && eq >= 1) {
            if (A[(int)eq] == A[pos]) ans--;
        }
    } else {
        if (pos > L) ans += countPartners(pos, L, pos - 1);
        if (pos < R) ans += countPartners(pos, pos + 1, R);
    }

    return ans;
}

int main() {
    scanf("%d %d %lld", &N, &Q, &K);

    for (int i = 1; i <= N; i++) scanf("%d", &A[i]);

    int INF = Q + 1;
    for (int i = 1; i <= N; i++) p[i] = INF;

    for (int t = 1; t <= Q; t++) {
        scanf("%d", &D[t]);
        p[D[t]] = t;
    }

    for (int i = 1; i <= N; i++) {
        uval[i] = (ll)i + A[i];
        vval[i] = (ll)i - A[i];
    }

    ht_init(&htU);
    ht_init(&htV);

    Uarr = (Pair*)malloc(sizeof(Pair) * N);
    Varr = (Pair*)malloc(sizeof(Pair) * N);
    u_start = (int*)malloc(sizeof(int) * N);
    u_end = (int*)malloc(sizeof(int) * N);
    v_start = (int*)malloc(sizeof(int) * N);
    v_end = (int*)malloc(sizeof(int) * N);

    for (int i = 1; i <= N; i++) {
        Uarr[i - 1].val = uval[i];
        Uarr[i - 1].idx = i;
        Varr[i - 1].val = vval[i];
        Varr[i - 1].idx = i;
    }

    buildGroups(Uarr, N, &htU, u_start, u_end);
    buildGroups(Varr, N, &htV, v_start, v_end);

    ll initial = 0;
    for (int i = 1; i <= N; i++) {
        initial += countPartners(i, i + 1, N);
    }

    int *st = (int*)malloc(sizeof(int) * (N + 1));
    int top = 0;

    for (int i = 1; i <= N; i++) {
        while (top > 0 && p[st[top - 1]] >= p[i]) top--;
        prev_less[i] = (top > 0) ? st[top - 1] : 0;
        st[top++] = i;
    }

    top = 0;
    for (int i = N; i >= 1; i--) {
        while (top > 0 && p[st[top - 1]] >= p[i]) top--;
        next_less[i] = (top > 0) ? st[top - 1] : N + 1;
        st[top++] = i;
    }
    free(st);

    ll *rem = (ll*)calloc(Q + 1, sizeof(ll));

    for (int t = 1; t <= Q; t++) {
        int x = D[t];
        int L = prev_less[x] + 1;
        int R = next_less[x] - 1;

        ll r = 0;

        if (L <= x - 1) r += countPartners(x, L, x - 1);
        if (x + 1 <= R) r += countPartners(x, x + 1, R);

        int leftLen = x - L;
        int rightLen = R - x;

        if (leftLen <= rightLen) {
            for (int i = L; i <= x - 1; i++) {
                r += countPartners(i, x + 1, R);
            }
        } else {
            for (int j = x + 1; j <= R; j++) {
                r += countPartners(j, L, x - 1);
            }
        }

        rem[t] = r;
    }

    ll ans = initial;
    printf("%lld\n", ans);

    for (int t = 1; t <= Q; t++) {
        ans -= rem[t];
        printf("%lld\n", ans);
    }

    return 0;
}
